//! 🔗️ Typed fixed read leases retain original roots through independently admitted ownership closure.

use crate::{ErasedSnapshotRetirement,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneSource,RetainedCloneStep},retirement::{RetireOwned,RetirementCursor,RetirementStep,shared::SharedControlledRetirement}};
use std::{mem::size_of,sync::{Arc,Mutex,TryLockError}};

const READ_OWNERSHIP_CAPACITY:usize=1024;
struct ReadOwnershipState<T>{roots:[Option<Arc<T>>;READ_OWNERSHIP_CAPACITY],issued:[bool;READ_OWNERSHIP_CAPACITY],cursor:usize}
impl<T> Default for ReadOwnershipState<T>{fn default()->Self{Self{roots:std::array::from_fn(|_|None),issued:[false;READ_OWNERSHIP_CAPACITY],cursor:0}}}

/// 🧷️ Fixed caller-owned slots retain immutable roots through granted issue and explicit return.
pub struct ReadOwnershipRegistry<T:RetireOwned+Sync>{state:Mutex<ReadOwnershipState<T>>}
impl<T:RetireOwned+Sync> ReadOwnershipRegistry<T>{
    pub fn constructor_capacity_bytes()->usize{crate::retirement::shared::arc_bytes::<Self>()}
    pub fn admit(grant:RetainedCloneGrant)->Result<(Arc<Self>,RetainedCloneProgress),ValueError>{
        if !T::controlled_retirement_supported(){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"read root has no controlled retirement authority"));}
        if grant.maximum_items==0{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"read registry birth requires one item"));}
        if grant.maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"read registry birth requires depth"));}
        let bytes=Self::constructor_capacity_bytes();
        if grant.maximum_capacity_bytes<bytes{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"read registry birth requires its complete capacity"));}
        Ok((Arc::new(Self{state:Mutex::new(ReadOwnershipState::default())}),RetainedCloneProgress{copied_items:1,retained_capacity_bytes:bytes,..Default::default()}))
    }
    pub fn try_issue(self:&Arc<Self>,root:Arc<T>,grant:RetainedCloneGrant)->Result<(ReadCustody<T>,RetainedCloneProgress),(ValueError,Arc<T>)>{
        if grant.maximum_items==0{return Err((ValueError::literal(ValueRefusalKind::WorkLimit,"read issue requires one item"),root));}
        if grant.maximum_depth==0{return Err((ValueError::literal(ValueRefusalKind::DepthLimit,"read issue requires depth"),root));}
        let mut state=match self.state.try_lock(){Ok(state)=>state,Err(TryLockError::WouldBlock)=>return Err((ValueError::literal(ValueRefusalKind::WorkLimit,"read registry is contended"),root)),Err(TryLockError::Poisoned(_))=>return Err((ValueError::literal(ValueRefusalKind::InvariantViolated,"read registry is poisoned"),root))};
        let Some(slot)=state.roots.iter().position(Option::is_none)else{return Err((ValueError::literal(ValueRefusalKind::OwnershipLimit,"read registry has no admitted slot"),root));};
        state.roots[slot]=Some(Arc::clone(&root));state.issued[slot]=true;
        Ok((ReadCustody{root:Some(root),registry:Some(Arc::clone(self)),root_close:None,registry_close:None,slot,returned:false},RetainedCloneProgress{copied_items:1,..Default::default()}))
    }
    pub fn set_cleanup_cursor(&self,cursor:usize)->Result<(),ValueError>{
        if cursor>=READ_OWNERSHIP_CAPACITY{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"read visit cursor exceeds fixed slots"));}
        self.state.try_lock().map_err(lock_refusal)?.cursor=cursor;Ok(())
    }
    pub fn take_returned(&self,grant:RetainedCloneGrant)->Result<(Option<Arc<T>>,RetainedCloneProgress),ValueError>{
        if grant.maximum_items==0{return Ok((None,Default::default()));}
        if grant.maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"read return requires depth"));}
        let mut state=self.state.try_lock().map_err(lock_refusal)?;
        for offset in 0..READ_OWNERSHIP_CAPACITY{
            let slot=(state.cursor+offset)%READ_OWNERSHIP_CAPACITY;
            if state.roots[slot].is_none(){continue;}
            state.cursor=(slot+1)%READ_OWNERSHIP_CAPACITY;
            let root=if state.issued[slot]{None}else{state.roots[slot].take()};
            return Ok((root,RetainedCloneProgress{copied_items:1,..Default::default()}));
        }
        Ok((None,Default::default()))
    }
}
fn lock_refusal<T>(error:TryLockError<T>)->ValueError{match error{TryLockError::WouldBlock=>ValueError::literal(ValueRefusalKind::WorkLimit,"read registry is contended"),TryLockError::Poisoned(_)=>ValueError::literal(ValueRefusalKind::InvariantViolated,"read registry is poisoned")}}

/// 👓️ One issued reader retains its original root and registry authority until funded cancellation.
pub struct ReadCustody<T:RetireOwned+Sync>{root:Option<Arc<T>>,registry:Option<Arc<ReadOwnershipRegistry<T>>>,root_close:Option<SharedControlledRetirement<T>>,registry_close:Option<SharedControlledRetirement<ReadOwnershipRegistry<T>>>,slot:usize,returned:bool}
impl<T:RetireOwned+Sync> ReadCustody<T>{
    pub fn get(&self)->&T{self.root.as_deref().expect("read custody remains borrowable before return")}
    pub fn source_capacity_bytes(&self)->usize{RetainedCloneSource::<T>::constructor_capacity_bytes::<Arc<ReadOwnershipRegistry<T>>>()}
    pub fn admit_source(&self,grant:RetainedCloneGrant)->Result<(RetainedCloneSource<T>,RetainedCloneProgress),ValueError>{
        let root=self.root.as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"returned read cannot issue a source"))?;
        let registry=self.registry.as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"read lost its registry authority"))?;
        RetainedCloneSource::admit(Arc::clone(root),Arc::clone(registry),grant).map_err(|(error,_,_)|error)
    }
}
impl<T:RetireOwned+Sync> ErasedSnapshotRetirement for ReadCustody<T>{
    fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
        if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}
        if grant.maximum_items==0{return Ok(RetainedCloneStep::Progress(Default::default()));}
        if grant.maximum_depth<self.next_depth_demand()?{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"read return exceeds admitted depth"));}
        if !self.returned{
            self.registry.as_ref().unwrap().state.try_lock().map_err(lock_refusal)?.issued[self.slot]=false;self.returned=true;
            self.root_close=Some(SharedControlledRetirement::lease(self.root.take().unwrap()));
            return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}));
        }
        if let Some(owner)=self.root_close.as_mut(){if owner.terminal_is_empty(){self.root_close=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}));}return owner.step(grant).map(|step|RetainedCloneStep::Progress(step.progress()));}
        if let Some(registry)=self.registry.take(){self.registry_close=Some(SharedControlledRetirement::lease(registry));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}));}
        if let Some(owner)=self.registry_close.as_mut(){if owner.terminal_is_empty(){self.registry_close=None;return Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,..Default::default()}));}return owner.step(grant).map(|step|RetainedCloneStep::Progress(step.progress()));}
        Ok(RetainedCloneStep::Complete(Default::default()))
    }
    fn terminal_is_empty(&self)->bool{self.returned&&self.root.is_none()&&self.registry.is_none()&&self.root_close.is_none()&&self.registry_close.is_none()}
    fn next_copy_byte_demand(&self)->Result<usize,ValueError>{if let Some(owner)=self.root_close.as_ref(){owner.next_copy_byte_demand()}else if let Some(owner)=self.registry_close.as_ref(){owner.next_copy_byte_demand()}else{Ok(0)}}
    fn next_capacity_byte_demand(&self,copy:usize)->Result<usize,ValueError>{if let Some(owner)=self.root_close.as_ref(){owner.next_capacity_byte_demand(copy)}else if let Some(owner)=self.registry_close.as_ref(){owner.next_capacity_byte_demand(copy)}else{Ok(0)}}
    fn next_release_byte_demand(&self)->Result<usize,ValueError>{if let Some(owner)=self.root_close.as_ref(){owner.next_release_byte_demand()}else if let Some(owner)=self.registry_close.as_ref(){owner.next_release_byte_demand()}else{Ok(0)}}
    fn next_depth_demand(&self)->Result<usize,ValueError>{if let Some(owner)=self.root_close.as_ref(){owner.next_depth_demand()}else if let Some(owner)=self.registry_close.as_ref(){owner.next_depth_demand()}else{Ok(usize::from(!self.returned))}}
}
impl<T:RetireOwned+Sync> Drop for ReadCustody<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"read custody abandoned original ownership");}}

struct ReadOwnershipRetirement<T>{state:ReadOwnershipState<T>}
impl<T:RetireOwned+Sync> RetirementCursor for ReadOwnershipRetirement<T>{
    fn close_step(&mut self,grant:RetainedCloneGrant)->RetirementStep{
        if self.terminal_is_empty(){return RetirementStep::Complete;}
        if grant.maximum_items==0{return RetirementStep::BudgetExhausted;}
        let slot=self.state.roots.iter().position(Option::is_some).unwrap();
        if self.state.issued[slot]{return RetirementStep::Failure(ValueError::literal(ValueRefusalKind::InvariantViolated,"read registry retirement contains an outstanding reader"));}
        let root=self.state.roots[slot].as_ref().unwrap();
        if grant.maximum_capacity_bytes<root.retirement_birth_bytes().unwrap(){return RetirementStep::BudgetExhausted;}
        RetirementStep::Child(self.state.roots[slot].take().unwrap().retirement())
    }
    fn terminal_is_empty(&self)->bool{self.state.roots.iter().all(Option::is_none)}
    fn next_birth_bytes(&self,_:usize)->Option<usize>{self.state.roots.iter().find_map(|root|root.as_ref().map(RetireOwned::retirement_birth_bytes)).unwrap_or(Some(0))}
