struct RegistryRetirement<T:RetireOwned+Sync> {owner:ManuallyDrop<ReadLeaseRegistry<T>>,active:Option<SharedControlledRetirement<T>>}
impl<T:RetireOwned+Sync> RetirementCursor for RegistryRetirement<T> {
